                { name = "Inferno", nameEn = "Inferno", icon = "Interface\\Icons\\Spell_Shadow_Summoninfernal", id = 1122, status = "same", learnLv = 50, races = "", reason = "", cost = "100%基础法力值", range = "30码距离", cast = "2 seccasting time", cd = "1小时冷却时间", desc = "从扭曲虚空中召来一颗流星，对其着陆区域的所有敌人造成200点火焰伤害，并使它们昏迷2秒。一个巨大的地狱火恶魔将从着陆点出现，并被施法者控制5分钟。如果控制失效，则施法者必须征服地狱火才能继续指挥它。只能在户外使用。", isTalent = false },
                { name = "Portal of Summoning", nameEn = "Portal of Summoning", icon = "Interface\\Icons\\Inv_Misc_Rune_10", id = 437169, status = "new", learnLv = 60, races = "", reason = "经典旧世没有；探索赛季有同名法术", cost = "100%基础法力值", range = "30码距离", cast = "需引导", cd = "1小时冷却时间", desc = "开启一个仪式，制造出一道传送门。2名团队成员就可以使用这道传送门来召唤队友。仪式需要施法者和2名队友协力才能完成。所有参与召唤的队友都必须不在战斗状态中，使用右键点击传送门，并且在召唤完成之前不得移动。", isTalent = false },
                { name = "Ritual of Doom", nameEn = "Ritual of Doom", icon = "Interface\\Icons\\Spell_Shadow_Antimagicshell", id = 18540, status = "same", learnLv = 60, races = "", reason = "", cost = "100%基础法力值", range = "30码距离", cast = "需引导", cd = "1小时冷却时间", desc = "进行祭祀仪式，随机牺牲一个参与者以召唤出一个末日守卫。你必须立即征服末日守卫，否则它就会攻击参与仪式者。需要施法者和4个队友共同进行仪式，所有参与者都必须使用右键点击传送门，在完成仪式之前不得移动。", isTalent = false },
                { name = "Demonic Sacrifice", nameEn = "Demonic Sacrifice", icon = "Interface\\Icons\\Spell_Shadow_Psychicscream", id = 18788, status = "talent", learnLv = nil, races = "", reason = "天赋：投入天赋点数即可获得，训练师不教；经典旧世中也是天赋", cost = "", range = "100码距离", cast = "Instant cast", cd = "", desc = "激活后，牺牲你召唤的恶魔来强化你力量的相反面向，使你获得一个持续2小时的效果。如果召唤任何恶魔，该效果会被取消。\n\n小鬼：使你的暗影伤害提高15%。\n\n虚空行者：每4秒恢复总法力值的2%。\n\n魅魔/夜魔：使你的火焰伤害提高15%。\n\n地狱猎犬：每4秒恢复总生命值的3%。", classic = "激活之后，牺牲你当前所召唤的恶魔，使你获得一种特殊效果，持续30分钟。如果在此期间你召唤任意一个恶魔，该效果就会被取消。\n\n小鬼：使你的火焰技能伤害提高15%。\n\n虚空行者：使你每4秒回复3%的生命值。\n\n魅魔/夜魔：使你的暗影技能伤害提高15%。\n\n地狱犬：使你每4秒回复2%的法力值。", isTalent = true },
                { name = "Fel Domination", nameEn = "Fel Domination", icon = "Interface\\Icons\\Spell_Nature_Removecurse", id = 18708, status = "talent", learnLv = nil, races = "", reason = "天赋：投入天赋点数即可获得，训练师不教；经典旧世中也是天赋", cost = "", range = "", cast = "Instant cast", cd = "5 min cooldown", desc = "你的下一个召唤小鬼、虚空行者、魅魔、夜魔或地狱猎犬的法术施法时间减少5.5秒，法力消耗减少50%。", isTalent = true },
                { name = "Soul Link", nameEn = "Soul Link", icon = "Interface\\Icons\\Spell_Shadow_Gathershadows", id = 19028, status = "talent", learnLv = nil, races = "", reason = "天赋：投入天赋点数即可获得，训练师不教；经典旧世中也是天赋", cost = "20%基础法力值", range = "100码距离", cast = "Instant cast", cd = "", desc = "激活时，施法者受到的所有伤害有30%由你的小鬼、虚空行者、魅魔、夜魔或地狱猎犬恶魔承受。此外，恶魔和主人造成的伤害都提高3%。只要恶魔处于激活状态，该效果就会持续。", classic = "激活之后，施法者所承受的伤害有30%被你的小鬼、虚空行者、魅魔、地狱猎犬、恶魔卫士等恶魔分担。另外，恶魔和其主人的任何攻击所造成的伤害都提高3%。只要恶魔保持激活状态，该效果就一直持续。", isTalent = true },
